import{_ as a,o as i,c as s,a2 as n}from"./chunks/framework.CeYlivdO.js";const u=JSON.parse('{"title":"Part 1: Building an STM32 Development Toolchain from Scratch — Cross-Compilation Principles and Installation Guide","description":"","frontmatter":{"title":"Part 1: Building an STM32 Development Toolchain from Scratch — Cross-Compilation Principles and Installation Guide","description":"","tags":["beginner","cpp-modern","stm32f1"],"difficulty":"beginner","platform":"stm32f1","chapter":14,"order":1},"headers":[],"relativePath":"en/vol8-domains/embedded/00-env-setup/01-toolchain-setup.md","filePath":"en/vol8-domains/embedded/00-env-setup/01-toolchain-setup.md","lastUpdated":null}'),t={name:"en/vol8-domains/embedded/00-env-setup/01-toolchain-setup.md"};function o(l,e,r,c,h,d){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="part-1-building-an-stm32-toolchain-from-scratch-—-cross-compilation-principles-and-installation-guide" tabindex="-1">Part 1: Building an STM32 Toolchain from Scratch — Cross-Compilation Principles and Installation Guide <a class="header-anchor" href="#part-1-building-an-stm32-toolchain-from-scratch-—-cross-compilation-principles-and-installation-guide" aria-label="Permalink to &quot;Part 1: Building an STM32 Toolchain from Scratch — Cross-Compilation Principles and Installation Guide&quot;">​</a></h1><blockquote><p>For everyone who wants to work with STM32 on Linux but feels dizzy from the barrage of toolchain jargon. This article documents our complete process of setting up an ARM cross-compilation environment from scratch, including why we cross-compile, what each tool does, and how to install everything on Ubuntu and Arch Linux respectively.</p></blockquote><hr><h2 id="why-i-m-writing-this-tutorial" tabindex="-1">Why I&#39;m Writing This Tutorial <a class="header-anchor" href="#why-i-m-writing-this-tutorial" aria-label="Permalink to &quot;Why I&#39;m Writing This Tutorial&quot;">​</a></h2><p>To be honest, I couldn&#39;t stand Keil&#39;s antiquated workflow anymore. It&#39;s 2024, and we&#39;re still stuck with a closed-source IDE that only runs on Windows, featuring half-baked code completion and a debugger UI that looks like it belongs in the last century. Worst of all, it eats up several gigabytes of my C: drive. The dealbreaker for me is that I&#39;ve grown completely accustomed to my Linux development environment — writing code with Vim/Neovim, getting completions from clangd, and managing builds with CMake. This toolchain feels natural and effortless on any project.</p><p>But things aren&#39;t that simple. When I first tried to flash a program to the STM32F103C8T6 (that dirt-cheap Blue Pill board) from Linux, I found that the online tutorials were an absolute disaster. Some were still hand-writing compilation rules in Makefiles, others pulled out PlatformIO as a black box that hides everything, and some simply said, &quot;Just use Keil, it&#39;s not worth the hassle on Linux.&quot; The most absurd ones were the so-called &quot;from scratch&quot; tutorials that immediately threw a wall of commands at you to copy-paste, without explaining what <code>arm-none-eabi-gcc</code> does, what newlib is, or why a linker script is needed. If you follow along, things might work, but the moment something goes slightly wrong, you&#39;ll have absolutely no idea where to start troubleshooting.</p><p>I spent an entire weekend tearing this toolchain apart from the inside out. After falling into countless pitfalls, I finally mapped out the entire compile-and-flash pipeline. Now I&#39;m documenting this process in full — not to give you a &quot;copy-and-paste&quot; cheat sheet, but to walk you through truly understanding what each step does and why we do it. That way, when you encounter errors later, you&#39;ll know exactly which stage went wrong, instead of searching for answers like a headless fly.</p><hr><h2 id="let-s-be-clear-what-is-cross-compilation" tabindex="-1">Let&#39;s Be Clear: What Is Cross-Compilation <a class="header-anchor" href="#let-s-be-clear-what-is-cross-compilation" aria-label="Permalink to &quot;Let&#39;s Be Clear: What Is Cross-Compilation&quot;">​</a></h2><p>Before we start typing commands, there&#39;s one concept we must nail down — cross-compilation.</p><p>If you usually write programs that run on an x86-64 CPU, the compilation process is straightforward: you use <code>gcc</code> to compile your code, and the resulting executable runs on the very same machine. The compiler and the target platform of the program are identical; this is called &quot;native compilation.&quot;</p><p>But the STM32F103C8T6 uses an ARM Cortex-M3 core, and its instruction set is completely different from the x86-64 in your computer. Code compiled with the regular <code>gcc</code> on your computer is gibberish to the STM32 — like speaking Arabic to someone who only understands Chinese. So we need a &quot;translator&quot; — a compiler that runs on x86-64 Linux but generates ARM machine code. This is the cross-compiler.</p><p>So why is it called <code>arm-none-eabi-gcc</code> such a long, weird name? Breaking it down makes it perfectly clear:</p><ul><li><code>arm</code> is the target CPU architecture; the generated code is for ARM</li><li><code>none</code> means no OS vendor (more on this later)</li><li><code>eabi</code> stands for Embedded Application Binary Interface</li><li><code>gcc</code> is our familiar GNU Compiler Collection</li></ul><p>There&#39;s a detail here worth expanding on. The <code>none</code> field was originally meant to specify the OS vendor — for example, <code>arm-linux-eabi</code> means compiling for ARM devices running Linux. But our STM32 runs bare-metal programs without an OS backing it up, so we put <code>none</code> here. The difference between <code>eabi</code> and <code>eabihf</code> is that the latter supports hardware floating point, but the F103C8T6&#39;s Cortex-M3 only has a single-precision floating-point unit, so the regular <code>eabi</code> is sufficient.</p><p>Once you understand cross-compilation, you&#39;ll see why you can&#39;t just use the system&#39;s built-in <code>gcc</code>, and why you need an entire dedicated toolchain: the compiler, linker, debugger, <em>objcopy</em> (for converting ELF to binary), <em>size</em> (for checking the firmware size) — all of these tools must be &quot;cross&quot; versions.</p><hr><h2 id="what-does-the-toolchain-look-like" tabindex="-1">What Does the Toolchain Look Like <a class="header-anchor" href="#what-does-the-toolchain-look-like" aria-label="Permalink to &quot;What Does the Toolchain Look Like&quot;">​</a></h2><p>Before we actually install anything, I want to lay out the overall framework so you know which pieces we ultimately need to assemble.</p><p>Compiling an STM32 program and flashing it to the board requires roughly this pipeline:</p><p>First, at the source code level. Your C/C++ code goes through preprocessing, compilation, and assembly to become individual object files (<code>.o</code> files). This step uses <code>arm-none-eabi-gcc</code> (for C code) and <code>arm-none-eabi-g++</code> (for C++ code).</p><p>But object files alone aren&#39;t enough; they need &quot;glue&quot; to hold them together. This glue is the linker (<code>arm-none-eabi-ld</code>), whose job is to stitch all object files and libraries into a complete program according to specified rules. For STM32, the linking process is especially unique — you need to tell it where Flash starts, where RAM is, and how to allocate the heap and stack. These rules are written in a linker script (<code>.ld</code> file). The linker places the code and data sections in the correct positions according to this &quot;map&quot; in the script.</p><p>After linking is complete, you get an ELF (Executable and Linkable Format) file (<code>.elf</code>), which contains code, data, symbol tables, and a bunch of other information. But STM32&#39;s Flash only understands raw binary data; it doesn&#39;t need any symbol tables. So we use <code>arm-none-eabi-objcopy</code> to extract the &quot;meat&quot; from the ELF file, generating a <code>.bin</code> binary file. This file is what actually gets flashed into the Flash.</p><p>There are several choices for the flashing tool. The most common is the ST-Link V2, ST&#39;s official debugger/programmer, which communicates with the STM32 via SWD (Serial Wire Debug). On Linux, we need software to drive the ST-Link, and that software is OpenOCD (Open On-Chip Debugger). It can play two roles: first, writing firmware to Flash (flashing), and second, acting as a GDB Server so you can debug programs on the board using GDB.</p><p>Speaking of libraries, there&#39;s a point that often confuses beginners. ARM bare-metal programs can&#39;t directly use your computer&#39;s glibc (GNU C Library), because glibc is designed for OS environments and relies on a bunch of system calls. Embedded environments need newlib — a C standard library implementation designed specifically for bare-metal/embedded systems. More specifically, we use newlib-nano, a stripped-down version of newlib optimized for code size. After installing <code>arm-none-eabi-newlib</code>, the compiler can find headers like <code>&lt;stdint.h&gt;</code> and <code>&lt;string.h&gt;</code>, and the linker can get the necessary library function implementations.</p><p>The final piece is debugging. OpenOCD can run in GDB Server mode, listening on a certain port (3333 by default). You connect to it with <code>arm-none-eabi-gdb</code>, and you can single-step, set breakpoints, and inspect variables just like debugging a regular program. VSCode&#39;s Cortex-Debug plugin simply puts this entire workflow behind a graphical interface, so you don&#39;t have to type GDB commands manually.</p><p>Stringing it all together, the complete chain is: <strong>Source code → Cross-compilation → Linking (with linker script) → objcopy extracts binary → OpenOCD flashes → GDB debugs</strong>. Once you understand this chain, you&#39;ll know which stage each tool operates in, and when something goes wrong, you can quickly pinpoint whether it&#39;s a compilation, linking, or flashing issue.</p><hr><h2 id="alright-let-s-get-started" tabindex="-1">Alright, Let&#39;s Get Started <a class="header-anchor" href="#alright-let-s-get-started" aria-label="Permalink to &quot;Alright, Let&#39;s Get Started&quot;">​</a></h2><p>After laying out all those concepts, we can finally get our hands dirty. I&#39;ll cover both Ubuntu and Arch, but you&#39;ll quickly notice that the commands are actually pretty similar — it&#39;s all just package manager stuff.</p><p>Let&#39;s start with Ubuntu. I&#39;m using 22.04 LTS here, but the commands for 20.04 and 24.04 are basically identical, since they share the same software repositories. Open a terminal and update the package index first — it&#39;s a good habit:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then install all the packages we need in one go:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    gcc-arm-none-eabi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    gdb-arm-none-eabi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    openocd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    build-essential</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Let me explain what each of these packages does. <code>gcc-arm-none-eabi</code> is a bundle that includes the cross-compiler, linker, objcopy, size, and a whole set of tools. <code>gdb-arm-none-eabi</code> is the ARM version of GDB, used for debugging embedded programs. <code>openocd</code> we covered earlier; it handles flashing and acts as a GDB Server. <code>cmake</code> and <code>build-essential</code> are build tools, with the latter including essentials like make.</p><p>After installation, we can verify that the toolchain is actually in place:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-none-eabi-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>If everything is normal, you&#39;ll see output similar to this:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arm-none-eabi-gcc (Ubuntu 11.3.0-1ubuntu1~22.04) 11.3.0</span></span>
<span class="line"><span>Copyright (C) 2021 Free Software Foundation, Inc.</span></span>
<span class="line"><span>This is free software; see the source for copying conditions.  There is no warranty; not even for MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>The version number might differ, but as long as it prints the version info, the installation was successful. There&#39;s a small detail here: Ubuntu&#39;s package name is <code>gcc-arm-none-eabi</code>, without a version number — the repository automatically selects a &quot;stable and widely used&quot; version. If you need a specific version (like wanting the latest GCC 14), you&#39;d have to download a prebuilt toolchain from ARM&#39;s official website, manually extract it to a directory, and add the path to your <code>PATH</code> environment variable. But for an older chip like the F103C8T6, GCC 11 is more than enough; there&#39;s no need to bother with a newer version.</p><hr><h2 id="the-arch-linux-route" tabindex="-1">The Arch Linux Route <a class="header-anchor" href="#the-arch-linux-route" aria-label="Permalink to &quot;The Arch Linux Route&quot;">​</a></h2><p>If you&#39;re using Arch Linux (or Manjaro, which I use), package management is even more straightforward. Arch&#39;s advantage is fast software updates, so you get a fairly recent toolchain version.</p><p>The install command is a bit shorter than Ubuntu&#39;s:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arm-none-eabi-gcc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arm-none-eabi-binutils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arm-none-eabi-gdb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openocd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>There&#39;s one difference from Ubuntu here: Arch splits the tools into multiple packages. <code>arm-none-eabi-gcc</code> is the compiler itself, <code>arm-none-eabi-binutils</code> includes ld, objcopy, size, and other tools, and <code>arm-none-eabi-gdb</code> is the debugger. Ubuntu bundles all of these into <code>gcc-arm-none-eabi</code>, so fewer packages need to be installed.</p><p>Verify that the installation succeeded:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-none-eabi-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>On Arch, you&#39;ll most likely see GCC 13 or 14, since it rolls fast:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arm-none-eabi-gcc (GCC) 13.2.0</span></span>
<span class="line"><span>Copyright (C) 2023 Free Software Foundation, Inc.</span></span>
<span class="line"><span>This is free software; see the source for copying conditions.  There is no warranty; not even for MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>There&#39;s a pitfall here I need to warn you about in advance. After installing <code>arm-none-eabi-gcc</code> on Arch, you might find that headers like <code>&lt;stdint.h&gt;</code> can&#39;t be found during compilation, or you get a <code>cannot read spec file &#39;nano.specs&#39;</code> error at link time. The reason is the same in both cases — Arch&#39;s <code>arm-none-eabi-gcc</code> package doesn&#39;t include newlib, and you need to install an extra package from the AUR:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arm-none-eabi-newlib</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>If you don&#39;t have <code>yay</code> installed, you&#39;ll need to install this AUR helper first, or manually clone the PKGBUILD from the AUR to build it. I won&#39;t expand on this process — anyone using Arch should already be familiar with it.</p><p>Once newlib is installed, headers like <code>&lt;stdint.h&gt;</code> and <code>&lt;string.h&gt;</code> will be available, and <code>nano.specs</code> and <code>nosys.specs</code> will work properly. What do these two specs files do? <code>nano.specs</code> tells the linker to use newlib-nano (the stripped-down C library), while <code>nosys.specs</code> provides an empty system call implementation — after all, in a bare-metal environment there&#39;s no OS, so functions like <code>read()</code> and <code>write()</code> can&#39;t actually be implemented. Using nosys.specs prevents link errors.</p><hr><h2 id="where-are-we-now" tabindex="-1">Where Are We Now <a class="header-anchor" href="#where-are-we-now" aria-label="Permalink to &quot;Where Are We Now&quot;">​</a></h2><p>At this point, our toolchain installation is complete. Your system should now have:</p><ul><li>Cross-compiler (<code>arm-none-eabi-gcc/g++</code>)</li><li>Linker and toolchain utilities (<code>arm-none-eabi-ld</code>, <code>objcopy</code>, <code>size</code>)</li><li>Debugger (<code>arm-none-eabi-gdb</code>)</li><li>Flashing tool (OpenOCD)</li><li>Build system (CMake)</li><li>C standard library (newlib)</li></ul><p>But tools alone aren&#39;t enough. In the next article, we&#39;ll cover project structure — how to get ST&#39;s official HAL library, that tricky submodule issue, which startup file to pick, and how to write a linker script. That part is the real &quot;pitfall minefield,&quot; but for now, let&#39;s make sure the foundation is solid.</p><p>You can go ahead and verify that all tools can be invoked normally:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 验证编译器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-none-eabi-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 验证调试器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-none-eabi-gdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 验证烧录工具</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openocd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 验证 CMake</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>If all of these commands print version information, congratulations — you&#39;ve cleared the toolchain installation hurdle. In the next article, we&#39;ll dive straight into project structure and start building a real STM32 C++ project.</p>`,62)])])}const m=a(t,[["render",o]]);export{u as __pageData,m as default};
